# WAR — robust migrations: log each, try fallback paths, fail loudly (diagnose schema issue)
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-migrations-fix.ps1
$ErrorActionPreference = "Stop"
if (-not (Test-Path "src\deploy")) { Write-Host "ERROR: run from project root" -ForegroundColor Red; exit 1 }
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\deploy\persistence.ts"), [Convert]::FromBase64String($b64))
Write-Host "  wrote src/deploy/persistence.ts" -ForegroundColor Green
Write-Host "Then: npm run build; git add -A; git commit -m robust-migrations; git push" -ForegroundColor Cyan